# Base timestamp
BASE_2025 = datetime(2025, 1, 1, tzinfo=UTC)

logger = logging.getLogger(__name__)


def _sanitize_for_logging(obj: Any) -> Any:
    """Remove embedding vectors from objects for logging purposes.

    Recursively traverses dictionaries and lists to remove 'vector' fields
    and 'query_vector' fields while preserving all other data.

    Args:
        obj: Object to sanitize (dict, list, or other)

    Returns:
        Sanitized object with embeddings removed
    """
    if isinstance(obj, dict):
        sanitized = {}
        for key, value in obj.items():
            if key in ("vector", "query_vector"):
                # Replace embedding vectors with a placeholder
                if isinstance(value, list) and len(value) > 0:
                    sanitized[key] = f"<embedding_vector(length={len(value)})>"
                else:
                    sanitized[key] = "<embedding_vector>"
            elif key == "embeddings" and isinstance(value, list):
                # Replace embeddings list with summary
                sanitized[key] = f"<embeddings_list(length={len(value)})>"
            else:
                sanitized[key] = _sanitize_for_logging(value)
        return sanitized
    elif isinstance(obj, list):
        return [_sanitize_for_logging(item) for item in obj]
    else:
        return obj


# Pydantic models based on nvschema.proto
class Location(BaseModel):
    """Location model (lat, lon, alt)."""

    lat: float = Field(default=0.0, description="Latitude")
    lon: float = Field(default=0.0, description="Longitude")
    alt: float = Field(default=0.0, description="Altitude")


class Coordinate(BaseModel):
    """Coordinate model (x, y, z)."""

    x: float = Field(default=0.0, description="X coordinate")
    y: float = Field(default=0.0, description="Y coordinate")
    z: float = Field(default=0.0, description="Z coordinate")


class Embedding(BaseModel):
    """Embedding model."""

    vector: list[float] = Field(default_factory=list, description="Embedding vector")
    info: dict[str, str] = Field(default_factory=dict, description="Additional info")


class Query(BaseModel):
    """Query model."""

    id: str = Field(default="", description="Query ID")
    params: dict[str, str] = Field(default_factory=dict, description="Query parameters")
    prompts: dict[str, str] = Field(default_factory=dict, description="Query prompts")
    response: str = Field(default="", description="Query response")
    embeddings: list[Embedding] = Field(default_factory=list, description="Query embeddings")


class LLM(BaseModel):
    """LLM model."""

    info: dict[str, str] = Field(default_factory=dict, description="LLM info")
    queries: list[Query] = Field(default_factory=list, description="List of queries")
    vision_embeddings: list[Embedding] = Field(default_factory=list, description="Vision embeddings")


class Sensor(BaseModel):
    """Sensor model."""

    id: str = Field(default="", description="Sensor ID")
    type: str = Field(default="", description="Sensor type")
    description: str = Field(default="", description="Sensor description")
    location: Location | None = Field(default=None, description="Location")
    coordinate: Coordinate | None = Field(default=None, description="Coordinate")
    info: dict[str, str] = Field(default_factory=dict, description="Additional info")


class VisionLLM(BaseModel):
    """VisionLLM model based on nvschema.proto."""

    version: str = Field(default="1.0", description="VisionLLM version")
    timestamp: str | None = Field(default=None, description="Start timestamp (ISO format)")
    end: str | None = Field(default=None, description="End timestamp (ISO format)")
    start_frame_id: str = Field(default="", description="Start frame ID")
    end_frame_id: str = Field(default="", description="End frame ID")
    sensor: Sensor | None = Field(default=None, description="Sensor information")
    llm: LLM | None = Field(default=None, description="LLM data")
    info: dict[str, str] = Field(default_factory=dict, description="Additional info")


class QueryInput(BaseModel):
    """Query input model for schema validation."""

    id: str = Field(default="", description="Query ID")
    params: dict[str, str] = Field(default_factory=dict, description="Query parameters")
    prompts: dict[str, str] = Field(default_factory=dict, description="Query prompts")
    response: str = Field(default="", description="Query response")
    embeddings: list[dict[str, Any]] = Field(default_factory=list, description="Query embeddings")


class EmbedSearchConfig(FunctionBaseConfig, name="embed_search"):  # type: ignore[call-arg,misc]
    """Configuration for the Embed Search tool."""

    cosmos_embed_endpoint: str = Field(
        ...,
        description="The URL of the backend to use for video ingestion.",
    )
    es_endpoint: str = Field(
        ...,
        description="The URL of the Elasticsearch endpoint to use for video ingestion.",
    )
    es_index: str = Field(
        default="video_embeddings",
        description="The index of the Elasticsearch to use for video ingestion.",
    )
    vst_external_url: str = Field(
        ...,
        description="The external VST URL for client-facing URLs.",
    )
    vst_internal_url: str | None = Field(
        default=None,
        description="The internal VST URL for validation requests. If not provided, uses vst_external_url.",
    )
    default_max_results: int = Field(
        default=100,
        description="Maximum number of results to return when top_k is not specified.",
    )
    video_clip_tool: FunctionRef = Field(
        ...,
        description="The function reference of the video clip tool to get the video URL.",
    )


def _str_input_converter(input: str) -> QueryInput:
    """Convert string input to QueryInput Pydantic model."""
    try:
        input_dict = json.loads(input)
        logger.info(f"Input dict: {input_dict}")
        # If it's already a Query JSON format, create QueryInput directly
        if "params" in input_dict or "prompts" in input_dict:
            return QueryInput(**input_dict)
        else:
            # Not in Query format, treat entire input as query string
            logger.warning(f"Input not in Query format, treating as query string: {input}")
            return QueryInput(id="", params={"query": input})
    except Exception as e:
        logger.exception(f"Error parsing input to QueryInput, using as query string: {input}, error: {e}")
        return QueryInput(id="", params={"query": input})


def _chat_request_input_converter(request: ChatRequest) -> QueryInput:
    """Convert ChatRequest to QueryInput Pydantic model."""
    try:
        content = request.messages[-1].content
        input_dict = json.loads(content)
        logger.info(f"Input dict: {input_dict}")
        # If it's already a Query JSON format, create QueryInput directly
        if "params" in input_dict or "prompts" in input_dict:
            return QueryInput(**input_dict)
        else:
            # Not in Query format, treat entire content as query string
            logger.warning(f"Input not in Query format, treating as query string: {content}")
            return QueryInput(id="", params={"query": content})
    except Exception as e:
        logger.exception(
            f"Error parsing input to QueryInput, using as query string: {request.messages[-1].content}, error: {e}"
        )
        return QueryInput(id="", params={"query": request.messages[-1].content})


def _to_str_output(vision_llm_output: VisionLLM) -> str:
    """Convert VisionLLM to JSON string."""
    return vision_llm_output.model_dump_json()


def _to_incidents_output(vision_llm_output: VisionLLM) -> str:
    """Format VisionLLM results as incidents JSON wrapped in <incidents> tags."""
    incidents = []

    # Extract query embedding vector
    query_embedding: list[float] = []
    if vision_llm_output.llm and vision_llm_output.llm.vision_embeddings:
        query_embedding = vision_llm_output.llm.vision_embeddings[0].vector

    # Extract results from queries
    if vision_llm_output.llm:
        for query in vision_llm_output.llm.queries:
            try:
                # Parse response JSON to get video metadata
                response_data = json.loads(query.response) if query.response else {}
                similarity_score = response_data.get("similarity_score", 0.0)

                incident = {
                    "Alert Details": {
                        "Alert Triggered": response_data.get("video_id", ""),
                        "video_description": response_data.get("description", ""),
                        "similarity_score": round(similarity_score, 2),
                        "query_embedding": query_embedding,
                        "description": response_data.get("description", ""),
                    },
                    "Clip Information": {
                        "Timestamp": vision_llm_output.timestamp or "",
                        "video_id": response_data.get("video_id", ""),
                        "video_url": response_data.get("video_url", ""),
                        "chunk_index": response_data.get("chunk_index", 0),
                        "start_time": response_data.get("start_time", 0.0),
                        "end_time": response_data.get("end_time", 0.0),
                        "duration": response_data.get("duration", 0.0),
                        "resolution": response_data.get("resolution", ""),
                    },
                }
                incidents.append(incident)
            except Exception as e:
                logger.error(f"Error parsing query response: {e}")
                continue

    incidents_json = {"incidents": incidents}
    json_string = json.dumps(incidents_json, indent=2)
    return f"<incidents>\n{json_string}\n</incidents>"


def _helper_markdown_bullet_list(vision_llm_output: VisionLLM) -> str:
    """Convert VisionLLM to markdown bullet list."""
    markdown = "```markdown\n"

    # Extract query embedding
    query_embedding: list[float] = []
    if vision_llm_output.llm and vision_llm_output.llm.vision_embeddings:
        query_embedding = vision_llm_output.llm.vision_embeddings[0].vector

    # Extract results from queries
    if vision_llm_output.llm:
        for query in vision_llm_output.llm.queries:
            try:
                response_data = json.loads(query.response) if query.response else {}
                markdown += (
                    f"- **Video ID:** `{response_data.get('video_id', '')}`\n"
                    f"  * Similarity Score: **{response_data.get('similarity_score', 0.0):.2f}**\n"
                    f"  * Video URL: {response_data.get('video_url', '')}\n"
                    f"  * Description: {response_data.get('description', '')}\n"
                    f"  * Chunk Index: {response_data.get('chunk_index', 0)}\n"
                    f"  * Start Time: {response_data.get('start_time', 0.0):.1f}s\n"
                    f"  * End Time: {response_data.get('end_time', 0.0):.1f}s\n"
                    f"  * Duration: {response_data.get('duration', 0.0):.1f}s\n"
                    f"  * Resolution: {response_data.get('resolution', '')}\n"
                    f"  * Timestamp: {vision_llm_output.timestamp or ''}\n\n"
                )
            except Exception as e:
                logger.error(f"Error formatting query result: {e}")
                continue

    markdown += f"* Query Embedding: {query_embedding}\n"
    markdown += "```"
    return markdown


def _to_chat_response(vision_llm_output: VisionLLM) -> ChatResponse:
    """Convert VisionLLM to ChatResponse."""
    incidents = _to_incidents_output(vision_llm_output)
    return ChatResponse.from_string(incidents, usage=Usage())


def _to_chat_response_chunk(vision_llm_output: VisionLLM) -> ChatResponseChunk:
    """Convert VisionLLM to ChatResponseChunk."""
    incidents = _to_incidents_output(vision_llm_output)
    return ChatResponseChunk.from_string(incidents)


async def _get_video_stream_url(video_clip_tool, stream_id: str, start_time: str, end_time: str) -> str:
    """Get video stream URL for a given sensor ID, start time, and end time."""
    logger.info(f"Requesting video URL: stream_id={stream_id}, start_time={start_time}, end_time={end_time}")

    # Parse ISO timestamps and compute seconds offset from BASE_2025 (video start time)
    start_time_dt = datetime.fromisoformat(start_time.replace("Z", "+00:00"))
    if start_time_dt.tzinfo is None:
        start_time_dt = start_time_dt.replace(tzinfo=UTC)
    start_time_seconds = (start_time_dt - BASE_2025).total_seconds()

    end_time_dt = datetime.fromisoformat(end_time.replace("Z", "+00:00"))
    if end_time_dt.tzinfo is None:
        end_time_dt = end_time_dt.replace(tzinfo=UTC)
    end_time_seconds = (end_time_dt - BASE_2025).total_seconds()

    video_clip_output = await video_clip_tool.ainvoke(
        {"sensor_id": stream_id, "start_time": start_time_seconds, "end_time": end_time_seconds}
    )
    logger.info(f"Video clip output: {video_clip_output}")
    video_url = video_clip_output.video_url

    logger.info(
        f"Got video URL: {video_url} for stream_id={stream_id}, start_seconds={start_time_seconds}, end_seconds={end_time_seconds}"
    )
    return video_url


async def _get_screenshot_url(
    vst_external_url: str, stream_id: str, timestamp: str, vst_internal_url: str | None = None
) -> str:
    """Get screenshot URL for a given stream ID and timestamp.

    Args:
        vst_external_url: External VST URL for client-facing URLs (returned to clients)
        stream_id: The stream ID
        timestamp: The timestamp for the screenshot
        vst_internal_url: Internal VST URL for validation requests (used internally).
                          If not provided, uses vst_external_url for validation.

    Returns:
        External screenshot URL if valid, empty string otherwise
    """
    # Build internal URL for validation (agent can reach internal IP)
    validation_base_url = vst_internal_url if vst_internal_url else vst_external_url
    validation_url = f"{validation_base_url}/vst/api/v1/replay/stream/{stream_id}/picture?startTime={timestamp}"

    # Build external URL for client response
    external_url = f"{vst_external_url}/vst/api/v1/replay/stream/{stream_id}/picture?startTime={timestamp}"

    is_valid = await _validate_screenshot_url(validation_url)

    return external_url if is_valid else ""


async def _validate_screenshot_url(url: str) -> bool:
    """Validate screenshot URL by GETting the image and checking if it's valid."""
    try:
        async with (
            aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=5.0)) as session,
            session.get(url, allow_redirects=True) as response,
        ):
            # Check if response is successful and content-type is an image
            if 200 <= response.status < 300:
                content_type = response.headers.get("content-type", "").lower()
                is_image = content_type.startswith("image/")
                logger.info(
                    f"Screenshot URL validation: status={response.status}, content-type={content_type}, is_image={is_image}"
                )
                return is_image
            else:
                logger.warning(f"Screenshot URL returned non-success status: {response.status}")
                return False
    except asyncio.TimeoutError as e:
        logger.warning(f"Screenshot URL validation timed out: {url}, error: {e}")
        return False
    except aiohttp.ClientError as e:
        logger.warning(f"Failed to validate screenshot URL {url}: {e}")
        return False
    except Exception as e:
        logger.warning(f"Failed to validate screenshot URL {url}: {e}")
        return False


@register_function(config_type=EmbedSearchConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def embed_search(config: EmbedSearchConfig, _builder: Builder) -> AsyncGenerator[FunctionInfo, None]:
    logger.info(f"Embed search config: {config}")
    es_client = AsyncElasticsearch(config.es_endpoint)
    embed_client: "EmbedClient" = CosmosEmbedClient(config.cosmos_embed_endpoint)
    video_clip_tool = await _builder.get_function(config.video_clip_tool)

    async def _embed_search(query_input: QueryInput) -> VisionLLM:
        """Perform embedding search using QueryInput and return VisionLLM."""

        # Extract parameters from QueryInput
        query_text = query_input.params.get("query", "")
        image_url = query_input.params.get("image_url", "")
        video_url = query_input.params.get("video_url", "")
        video_names_str = query_input.params.get("video_names", "")
        # top_k is optional - if not provided, return all matching results
        top_k_str = query_input.params.get("top_k", "")
        top_k: int | None = int(top_k_str) if top_k_str else None
        min_cosine_similarity = float(query_input.params.get("min_cosine_similarity", "0.0"))
        description = query_input.params.get("description", "")
        timestamp_start_str = query_input.params.get("timestamp_start", "")
        timestamp_end_str = query_input.params.get("timestamp_end", "")

        # Parse video_names if provided (can be JSON string or comma-separated)
        video_names: list[str] = []
        if video_names_str:
            try:
                # Try parsing as JSON array
                video_names = json.loads(video_names_str)
                if not isinstance(video_names, list):
                    video_names = [video_names_str]
            except Exception:
                # Try comma-separated string
                video_names = [v.strip() for v in video_names_str.split(",") if v.strip()]

        # Parse timestamps if provided
        # User timestamps are relative to 2025-01-01, ES also uses 2025-01-01 base
        timestamp_start: datetime | None = None
        timestamp_end: datetime | None = None
        if timestamp_start_str:
            try:
                user_ts = datetime.fromisoformat(timestamp_start_str.replace("Z", "+00:00"))
                if user_ts.tzinfo is None:
                    user_ts = user_ts.replace(tzinfo=UTC)
                timestamp_start = user_ts
            except Exception as e:
                logger.warning(f"Failed to parse timestamp_start: {e}")
        if timestamp_end_str:
            try:
                user_ts = datetime.fromisoformat(timestamp_end_str.replace("Z", "+00:00"))
                if user_ts.tzinfo is None:
                    user_ts = user_ts.replace(tzinfo=UTC)
                timestamp_end = user_ts
            except Exception as e:
                logger.warning(f"Failed to parse timestamp_end: {e}")

        # Get query embedding
        query_embedding: list[float] = []
        if query_input.embeddings:
            # Use pre-computed embedding if provided
            query_embedding = query_input.embeddings[0].get("vector", [])
        elif image_url:
            query_embedding = await embed_client.get_image_embedding(image_url)
        elif query_text:
            query_embedding = await embed_client.get_text_embedding(query_text.strip())
        elif video_url:
            query_embedding = await embed_client.get_video_embedding(video_url)
        else:
            raise ValueError("Either query, image_url, video_url, or embeddings must be provided in Query params.")

        # Build filter conditions
        filters: list[dict[str, Any]] = []

        # Add video_names filter if provided
        # video_name is extracted from sensor.info.url (filename) or sensor.info.path (filename)
        # So we filter on sensor.id, sensor.info.url (filename match), or sensor.info.path (filename match)
        if video_names:
            # Build should clauses for each video name
            should_clauses = []
            for vname in video_names:
                # Match filename in sensor.info.url using wildcard
                # Escape only wildcard characters (* and ?) for Elasticsearch wildcard queries
                # Other characters like ., _, - are treated literally
                escaped_vname = vname.replace("\\", "\\\\").replace("*", "\\*").replace("?", "\\?")
                # Use .keyword subfield for exact/wildcard matching (non-analyzed, more reliable for full filenames)
                should_clauses.append({"wildcard": {"sensor.info.url.keyword": f"*{escaped_vname}"}})
                should_clauses.append({"wildcard": {"sensor.info.url.keyword": f"*{escaped_vname}*"}})
                # Also try regex query on text field for partial matches (analyzed field, works for "car" etc.)
                regex_escaped = re.escape(vname)
                should_clauses.append({"regexp": {"sensor.info.url": f".*{regex_escaped}"}})

            filters.append(
                {
                    "bool": {
                        "should": should_clauses,
                        "minimum_should_match": 1,
                    }
                }
            )

        # Add description filter (sensor.description - use both keyword and text fields, with regex and wildcard)
        if description:
            # Escape wildcard characters for wildcard queries
            escaped_desc = description.replace("\\", "\\\\").replace("*", "\\*").replace("?", "\\?")
            # Escape regex special characters for regex queries
            regex_escaped_desc = re.escape(description)

            description_should_clauses = [
                # Text field matching (analyzed, for partial matches)
                {"match": {"sensor.description": description}},
                # Keyword field exact/wildcard matching (non-analyzed)
                {"wildcard": {"sensor.description.keyword": f"*{escaped_desc}*"}},
                {"wildcard": {"sensor.description.keyword": f"*{escaped_desc}"}},
                # Regex queries for both fields
                {"regexp": {"sensor.description": f".*{regex_escaped_desc}.*"}},
                {"regexp": {"sensor.description.keyword": f".*{regex_escaped_desc}.*"}},
            ]

            filters.append(
                {
                    "bool": {
                        "should": description_should_clauses,
                        "minimum_should_match": 1,
                    }
                }
            )

        # Add timestamp range filter
        # Use top-level timestamp and end fields
        # We need to match documents where:
        #   - timestamp >= timestamp_start
        #   - AND end <= timestamp_end
        if timestamp_start or timestamp_end:
            must_clauses = []

            # Start time condition: use top-level timestamp field
            if timestamp_start:
                must_clauses.append({"range": {"timestamp": {"gte": timestamp_start.isoformat()}}})

            # End time condition: use top-level end field
            if timestamp_end:
                must_clauses.append({"range": {"end": {"lte": timestamp_end.isoformat()}}})

            # Combine start and end conditions with AND logic
            if len(must_clauses) > 1:
                filters.append({"bool": {"must": must_clauses}})
            else:
                filters.append(must_clauses[0])

        # Adjust k based on filters and similarity threshold
        # When top_k is None, return all matching results (use config.default_max_results)
        # When min_cosine_similarity or filters are set, we need to fetch more results from ES
        # since some will be filtered out, then apply top_k after filtering
        if top_k is None:
            # No top_k limit - fetch up to max results from config
            k_value = config.default_max_results
        elif min_cosine_similarity >= -1.0 or filters:
            k_value = top_k * 5  # Fetch more to compensate for filtering
        else:
            k_value = top_k
        num_candidates = k_value * 2  # num_candidates should be >= k for better recall

        # Build nested KNN query (llm.vision_embeddings is nested)
        knn_query: dict[str, Any] = {
            "field": "llm.visionEmbeddings.vector",
            "query_vector": query_embedding,
            "k": k_value,
            "num_candidates": num_candidates,
        }
        # NOTE: Removing similarity threshold in ES knn nested query
        # as it doesn't work correctly. Post-filtering is done below instead.

        # Build nested query wrapping the KNN query
        nested_query: dict[str, Any] = {
            "nested": {
                "path": "llm.visionEmbeddings",
                "query": {
                    "knn": knn_query,
                },
                "inner_hits": {
                    "size": 1,  # Return which nested embedding matched
                },
            }
        }

        # Build search query with filters
        if filters:
            # Combine nested query with filters using bool query
            if len(filters) > 1:
                filter_clause = {"bool": {"must": filters}}
            else:
                filter_clause = filters[0]

            search_query = {
                "query": {
                    "bool": {
                        "must": [nested_query],
                        "filter": [filter_clause],
                    }
                },
                "size": k_value,
            }
        else:
            # No filters, just nested query
            search_query = {
                "query": nested_query,
                "size": k_value,
            }
        logger.debug(f"ES search_query:\n{json.dumps(search_query, indent=2)}")

        logger.info(f"Search query: {_sanitize_for_logging(search_query)}")

        try:
            response = await es_client.search(index=config.es_index, body=search_query)
        except ESNotFoundError as e:
            # Index doesn't exist - return empty result with informative error
            logger.error(f"Elasticsearch index '{config.es_index}' not found: {e}")
            raise ValueError(
                f"Search index '{config.es_index}' does not exist. "
                "Please ensure videos have been ingested before searching."
            ) from e

        # Convert ObjectApiResponse to dict for logging
        # Elasticsearch response objects have a .body attribute containing the actual response dict
        response_dict = response.body
        logger.info(
            f"ES search response (before processing): {json.dumps(_sanitize_for_logging(response_dict), indent=2)}"
        )

        # Create VisionLLM output
        vision_llm = VisionLLM(
            version="1.0",
            timestamp=datetime.now(UTC).isoformat(),
        )

        # Create LLM object with query embedding
        query_embedding_obj = Embedding(vector=query_embedding)
        llm = LLM(vision_embeddings=[query_embedding_obj])

        # Process results and convert to VisionLLM format
        results_processed = 0
        for hit in response["hits"]["hits"]:
            # Apply top_k limit after similarity filtering (skip if top_k is None - return all)
            if top_k is not None and results_processed >= top_k:
                break

            # ES score is normalized to [0, 1] range, UI sends min_cosine_similarity in [-1, 1] range
            # Convert ES score to cosine: cosine = (2 * _score) - 1
            similarity_score = 2 * hit["_score"] - 1
            if similarity_score < min_cosine_similarity:
                continue
            source = hit["_source"]

            # Only process results with "llm" field
            if "llm" not in source:
                logger.warning(f"Skipping result without 'llm' field: {hit.get('_id', 'unknown')}")
                continue

            # Parse the stored VisionLLM structure (handle empty/None safely)
            stored_llm_data = source.get("llm", {}) or {}
            queries_data = stored_llm_data.get("queries", [])
            if not isinstance(queries_data, list):
                queries_data = []

            result_query = Query(id=hit.get("_id") or "")

            if queries_data and len(queries_data) > 0:
                # Use the first query from the stored VisionLLM
                stored_query_data = queries_data[0] if isinstance(queries_data[0], dict) else {}
                result_query.id = stored_query_data.get("id") or result_query.id or ""
                # Parse existing response and add similarity_score
                try:
                    response_str = stored_query_data.get("response", "{}")
                    if response_str:
                        response_data = json.loads(response_str)
                        if not isinstance(response_data, dict):
                            response_data = {}
                    else:
                        response_data = {}

                    # Extract additional fields from source/sensor/params if not in response
                    sensor_data = source.get("sensor", {}) or {}
                    sensor_info = sensor_data.get("info", {}) or {}

                    # Debug logging for timestamp fields
                    logger.debug(
                        f"Timestamp sources - "
                        f"source.timestamp: {source.get('timestamp')}, source.end: {source.get('end')}"
                    )

                    video_url = sensor_info.get("url", "")
                    stream_id = sensor_data.get("id", "")

                    # 1. Extract video_name from sensor.info.url (filename) or sensor.info.path (filename)
                    if "video_name" not in response_data:
                        video_name = video_url.split("/")[-1] if video_url else ""
                        if video_name:
                            response_data["video_name"] = video_name

                    # 2. Extract description from sensor.description only (leave blank if not available)
                    if "description" not in response_data:
                        sensor_desc = sensor_data.get("description", "")
                        if sensor_desc:
                            response_data["description"] = sensor_desc
                        # Otherwise leave it blank (don't derive)

                    # 3. Extract timestamps: ES timestamps are already relative to 2025-01-01

                    # Extract start_time from source.timestamp
                    if "start_time" not in response_data:
                        es_timestamp = source.get("timestamp", "")

                        if es_timestamp:
                            try:
                                es_start_dt = datetime.fromisoformat(str(es_timestamp).replace("Z", "+00:00"))
                                if es_start_dt.tzinfo is None:
                                    es_start_dt = es_start_dt.replace(tzinfo=UTC)
                                response_data["start_time"] = es_start_dt.isoformat().replace("+00:00", "Z")
                            except Exception as e:
                                logger.warning(f"Failed to parse timestamp: {e}")
                                response_data["start_time"] = BASE_2025.isoformat().replace("+00:00", "Z")
                        else:
                            response_data["start_time"] = BASE_2025.isoformat().replace("+00:00", "Z")

                    # Extract end_time from source.end
                    if "end_time" not in response_data:
                        es_end = source.get("end", "")

                        if es_end:
                            try:
                                es_end_dt = datetime.fromisoformat(str(es_end).replace("Z", "+00:00"))
                                if es_end_dt.tzinfo is None:
                                    es_end_dt = es_end_dt.replace(tzinfo=UTC)
                                response_data["end_time"] = es_end_dt.isoformat().replace("+00:00", "Z")
                            except Exception as e:
                                logger.warning(f"Failed to parse end timestamp: {e}")
                                response_data["end_time"] = BASE_2025.isoformat().replace("+00:00", "Z")
                        else:
                            response_data["end_time"] = BASE_2025.isoformat().replace("+00:00", "Z")

                    # Log final calculated timestamps for debugging
                    logger.debug(
                        f"Final timestamps - start_time: {response_data.get('start_time')}, "
                        f"end_time: {response_data.get('end_time')}, stream_id: {stream_id}"
                    )

                    # 4. Set video_url and screenshot_url based on stream_id and timestamps
                    response_data["video_url"] = await _get_video_stream_url(
                        video_clip_tool, stream_id, response_data["start_time"], response_data["end_time"]
                    )
                    if response_data["video_url"]:
                        response_data["screenshot_url"] = await _get_screenshot_url(
                            config.vst_external_url,
                            stream_id,
                            response_data["start_time"],
                            vst_internal_url=config.vst_internal_url,
                        )
                    else:
                        response_data["screenshot_url"] = ""

                    # Always add similarity_score (use raw ES score in [0, 1] range)
                    response_data["similarity_score"] = round(similarity_score, 2)
                    result_query.response = json.dumps(response_data)
                except Exception as e:
                    # If response is not JSON, create new response with similarity_score
                    logger.warning(f"Error building response: {e}")
                    result_data = {
                        "similarity_score": round(similarity_score, 2),
                        "response": stored_query_data.get("response", "") or "",
                    }
                    result_query.response = json.dumps(result_data)
                # Copy params and prompts if available (handle None/empty safely)
                result_query.params = (stored_query_data.get("params") or {}).copy()
                result_query.prompts = (stored_query_data.get("prompts") or {}).copy()
                # Copy embeddings if available
                embeddings_list = stored_query_data.get("embeddings", [])
                if isinstance(embeddings_list, list):
                    result_query.embeddings = [
                        Embedding(
                            vector=emb_data.get("vector", []) if isinstance(emb_data.get("vector"), list) else [],
                            info=(emb_data.get("info") or {}).copy() if isinstance(emb_data.get("info"), dict) else {},
                        )
                        for emb_data in embeddings_list
                        if isinstance(emb_data, dict)
                    ]
                else:
                    result_query.embeddings = []
            else:
                # No queries in stored data, create minimal response with similarity_score
                result_query.response = json.dumps({"similarity_score": round(hit["_score"], 2)})

            llm.queries.append(result_query)

            # Extract VisionLLM metadata from source
            if source.get("timestamp"):
                try:
                    # ES timestamps are relative to 2025-01-01
                    es_ts = datetime.fromisoformat(str(source["timestamp"]).replace("Z", "+00:00"))
                    if es_ts.tzinfo is None:
                        es_ts = es_ts.replace(tzinfo=UTC)
                    vision_llm.timestamp = es_ts.isoformat().replace("+00:00", "Z")
                except Exception as e:
                    logger.exception(f"Failed to parse source timestamp '{source.get('timestamp')}': {e}")

            vision_llm.start_frame_id = source.get("startFrameId") or ""
            vision_llm.end_frame_id = source.get("endFrameId") or ""

            # Extract sensor if available
            sensor_data = source.get("sensor", {})
            if sensor_data:
                location = None
                if sensor_data.get("location"):
                    loc_data = sensor_data["location"]
                    if isinstance(loc_data, dict):
                        location = Location(
                            lat=loc_data.get("lat", 0.0),
                            lon=loc_data.get("lon", 0.0),
                            alt=loc_data.get("alt", 0.0),
                        )

                coordinate = None
                if sensor_data.get("coordinate"):
                    coord_data = sensor_data["coordinate"]
                    if isinstance(coord_data, dict):
                        coordinate = Coordinate(
                            x=coord_data.get("x", 0.0),
                            y=coord_data.get("y", 0.0),
                            z=coord_data.get("z", 0.0),
                        )

                sensor = Sensor(
                    id=sensor_data.get("id") or "",
                    type=sensor_data.get("type") or "",
                    description=sensor_data.get("description") or "",
                    location=location,
                    coordinate=coordinate,
                    info=(sensor_data.get("info") or {}).copy() if isinstance(sensor_data.get("info"), dict) else {},
                )
                vision_llm.sensor = sensor

            # Extract info if available (handle None/empty safely)
            info_data = source.get("info")
            if info_data and isinstance(info_data, dict):
                vision_llm.info.update(info_data)

            results_processed += 1

        vision_llm.llm = llm

        # Set end timestamp
        vision_llm.end = datetime.now(UTC).isoformat()

        logger.info(f"Found {results_processed} videos matching the query")
        logger.info(
            f"Embed search result (after processing): {json.dumps(_sanitize_for_logging(vision_llm.model_dump()), indent=2)}"
        )
        return vision_llm

    yield FunctionInfo.create(
        single_fn=_embed_search,
        description=_embed_search.__doc__,
        input_schema=QueryInput,
        single_output_schema=VisionLLM,
        converters=[
            _str_input_converter,
            _chat_request_input_converter,
            _to_chat_response,
            _to_str_output,
            _to_chat_response_chunk,
        ],
    )
